cd <scratch> && mv riot_patch-10-16b-notes.html riot_10.17.html; for p in 10-18 10-19 11-16 11-17 11-18 11-19; do mv riot_patch-$p-notes.html riot_${p/-/.}.html; done; rm -f riot_patch-*.html riot1017.html; ls; python3 - <<'EOF'
import re,json
s=open('riot_10.18.html').read()
m=re.search(r'<script id="__NEXT_DATA__" type="application/json">(.*?)</script>',s,re.S)
d=json.loads(m.group(1))
def walk(o,path=''):
    if isinstance(o,dict):
        for k,v in o.items(): walk(v,path+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): walk(v,path+f'[{i}]')
    elif isinstance(o,str) and len(o)>5000:
        print(path,len(o))
walk(d)
EOF
